        <details><summary>检索与分析范围 <Icon name="info" :size="13" /></summary><div class="scope-detail"><p>PubMed 命中 {{ state.scope.totalHits }} 篇，已获取 {{ state.scope.retrievedCount }} 篇，排除已标记撤稿 {{ report.excludedCount }} 篇。日期：{{ state.scope.dateFrom }} 至 {{ state.scope.dateTo }}；语言：{{ state.scope.language || '不限' }}；类型：{{ state.scope.articleTypes || '不限' }}。</p><div class="code-block">{{ state.scope.query }}</div><p v-if="report.mode === 'AI'">{{ report.sampling }} 模型：{{ report.model }}。仅提供标题与摘要，未自动核对全文。</p><p>生成于 {{ formatDate(report.generatedAt) }}。领域判断受检索范围、收录与摘要可得性影响；新颖性尚需补充检索。</p></div></details>
      </section>
      <div v-if="state.stale" class="evidence-notice amber" role="status"><Icon name="info" :size="17" /><span>文献库已变化，当前保留的是此前梳理结果。重新分析前请先导出需要保留的编辑内容。</span></div>
      <div v-if="job.status === 'RUNNING'" class="evidence-notice analysis-running" role="status"><span class="live-dot"></span><div>{{ job.message }}<div class="analysis-waiting-detail"><span v-if="job.sourceCount">已提交 {{ job.sourceCount }} 篇文献</span><span v-if="elapsedLabel">已等待 {{ elapsedLabel }}</span><span v-if="job.timeoutSeconds">模型请求最长等待 {{ Math.ceil(job.timeoutSeconds / 60) }} 分钟</span></div></div></div>
      <div v-if="job.status === 'FAILED'" class="inline-error" role="alert">{{ job.message }}</div>
      <div v-if="!activeModel()" class="evidence-notice"><Icon name="spark" :size="16" /><span>基础图谱和人工笔记可以直接使用。配置模型后，可辅助提炼中文主题、梳理笔记和子议题。</span><router-link to="/settings/models">配置模型 <span aria-hidden="true">→</span></router-link></div>
      <div class="evidence-metrics"><div><span class="metric-label">纳入梳理</span><strong>{{ report.analyzedCount }}<small>篇文献</small></strong><span class="metric-foot">{{ report.missingAbstractCount }} 篇缺少摘要</span></div><div><span class="metric-label">细分方向</span><strong>{{ report.topics.length }}<small>个方向</small></strong><span class="metric-foot">支持主题交叉与人工调整</span></div><div><span class="metric-label">已有综述</span><strong>{{ report.reviews.length }}<small>篇已识别</small></strong><span class="metric-foot">按 PubMed 文章类型识别</span></div><div><span class="metric-label">候选子议题</span><strong>{{ report.candidates.length }}<small>张选题卡</small></strong><span class="metric-foot">{{ report.candidates.filter(c => c.status === 'KEEP').length }} 项已保留 · 新颖性待核实</span></div></div>
      <div v-if="!report.analyzedCount" class="surface empty-state"><div class="empty-icon"><Icon name="book" :size="26" /></div><h3>先建立一份文献资料库</h3><p>获取文献标题和摘要后，即可查看主题分布并开始梳理。</p><el-button type="primary" @click="$router.push(`/scan/new?run=${id}`)">返回检索方案</el-button></div>
      <el-tabs v-else v-model="tab" class="evidence-tabs" @tab-change="visibleSourceCount = 8">
        <el-tab-pane label="领域图谱" name="map" /><el-tab-pane label="综述覆盖" name="reviews" /><el-tab-pane label="梳理笔记" name="notes" /><el-tab-pane label="候选子议题" name="topics" />
      </el-tabs>
      <template v-if="report.analyzedCount">
        <div v-if="tab === 'map' || tab === 'notes'" class="evidence-layout">
          <aside class="evidence-topic-list surface"><div class="topic-list-heading"><strong>细分方向</strong><span>{{ report.topics.length }}</span></div><button v-for="(topic,i) in report.topics" :key="topic.id" :class="['evidence-topic-button', { selected: selectedId === topic.id }]" :aria-pressed="selectedId === topic.id" @click="selectTopic(topic.id)"><span class="topic-index">{{ String(i+1).padStart(2,'0') }}</span><span><strong>{{ topic.name }}</strong><small>{{ topic.pmids.length }} 篇关联 · {{ topic.notes.length }} 条笔记</small></span><Icon name="arrow" :size="14" /></button><div class="topic-list-help">方向可交叉，文献数不能相加作为总量。<template v-if="report.unassignedCount && report.mode !== 'AI'"> {{ report.unassignedCount }} 篇未命中当前主题词。</template></div></aside>
          <div class="evidence-main-column" v-if="selected">
            <section class="surface direction-header"><div class="direction-top"><div><div class="eyebrow">RESEARCH DIRECTION {{ report.topics.indexOf(selected)+1 }}</div><h2>{{ selected.name }}</h2></div><el-button size="small" :disabled="running" @click="editTopic"><Icon name="edit" :size="14" />编辑方向</el-button></div><p>{{ selected.description }}</p><div class="direction-tags"><span class="pill">{{ selected.pmids.length }} 篇关联文献</span><span class="pill">{{ selectedSources.filter(s => s.isReview).length }} 篇相关综述</span><span :class="['pill', { green: selected.editorStatus === 'CONFIRMED' }]">{{ selected.editorStatus === 'CONFIRMED' ? '方向已确认' : '边界待核实' }}</span><span class="pill">成熟度：{{ maturityLabels[selected.maturity] || '尚未评估' }}{{ selected.maturity !== 'UNASSESSED' ? '（人工）' : '' }}</span></div><p v-if="selected.editorNote" class="direction-editor-note">编辑备注：{{ selected.editorNote }}</p></section>
            <template v-if="tab === 'map'">
              <section class="surface"><div class="surface-header"><h2><Icon name="connection" :size="17" />主题关联图</h2><span class="small muted">连线 = 共同文献</span></div><EvidenceGraph :topics="report.topics" :selected="selectedId" @select="selectTopic" /><p class="graph-caption">编号对应方向列表；节点大小表示文献量，连线表示共同文献。悬浮查看主题，点击切换方向。</p></section>
              <section class="surface"><div class="surface-header"><h2><Icon name="chart" :size="17" />文献发表时间分布</h2><span class="small muted">按真实发表月份统计</span></div><EvidenceGraph v-if="report.timeline.length" kind="timeline" :timeline="report.timeline" /><div v-else class="compact-empty">当前文献缺少可按月统计的日期。</div><p class="graph-caption">{{ report.undatedCount }} 篇缺少明确月份，未计入曲线；当前检索时间窗及收录延迟可能影响分布。</p></section>
            </template>
            <template v-else>
              <section v-for="(label,kind) in noteLabels" :key="kind" class="surface note-section"><div class="surface-header"><h2><span :class="['note-section-dot',kind.toLowerCase()]"></span>{{ label }}</h2><el-button size="small" :disabled="running" @click="editNote(null,kind)"><Icon name="plus" :size="13" />添加笔记</el-button></div><div class="surface-body"><template v-if="selected.notes.some(n => n.kind === kind)"><article v-for="note in selected.notes.filter(n => n.kind === kind)" :key="note.id" class="evidence-note"><div class="note-top"><span :class="['pill', { green: note.editorStatus === 'CONFIRMED' }]">{{ note.editorStatus === 'CONFIRMED' ? '编辑已确认' : '待核实草稿' }}</span><button class="text-button" :disabled="running" @click="editNote(note)">编辑笔记</button></div><p>{{ note.text }}</p><div class="citation-links"><button v-for="(citation,i) in note.citations" :key="i" class="citation-chip" @click="inspect(citation.pmid,citation)"><Icon name="book" :size="13" />PMID {{ citation.pmid }}<span>查看引文</span></button></div></article></template><p v-else class="empty-note">{{ emptyNotes[kind] }}</p></div></section>
              <section class="surface author-section"><div class="surface-header"><h2><Icon name="connection" :size="17" />相关作者线索</h2><span class="small muted">按本方向关联篇数排列</span></div><div class="surface-body"><p class="author-disclosure">来自本次文献作者信息；同名、机构、研究角色及邀稿适配性待核实。</p><article v-for="author in authors.slice(0,6)" :key="author.name" class="author-evidence"><div><strong>{{ author.name }}</strong><small>{{ author.pmids.length }} 篇相关文献 · 身份待核实</small></div><div class="author-emails"><template v-if="author.contacts.length"><a v-for="c in author.contacts" :key="c.email" :href="c.sourceUrl" target="_blank" rel="noopener noreferrer">{{ c.email }} <Icon name="external" :size="11" /></a></template><span v-else class="muted">邮箱：未找到</span><div><button v-for="pmid in author.pmids.slice(0,3)" :key="pmid" class="text-button" @click="inspect(pmid)">PMID {{ pmid }}</button></div></div></article><p v-if="!authors.length" class="empty-note">当前文献没有可展示的作者信息。</p></div></section>
            </template>
            <section class="surface"><div class="surface-header"><h2><Icon name="document" :size="17" />方向关联文献</h2><button class="text-button" @click="tab = tab === 'map' ? 'notes' : 'reviews'">{{ tab === 'map' ? '进入梳理笔记' : '查看综述覆盖' }} →</button></div><div class="direction-papers"><article v-for="source in selectedSources.slice(0,visibleSourceCount)" :key="source.pmid"><div><span :class="['paper-type-dot', { review: source.isReview }]"></span><button class="paper-title" @click="inspect(source.pmid)">{{ source.title }}</button></div><p><span>{{ source.pubdate || '日期未提供' }}</span><span>PMID {{ source.pmid }}</span><span v-if="source.isReview" class="pill">综述</span><span v-else>{{ source.pubtypes || '类型未提供' }}</span></p><small v-if="assignment(source.pmid)">{{ assignment(source.pmid) }}</small></article><button v-if="selectedSources.length > visibleSourceCount" class="show-more-papers" @click="visibleSourceCount += 20">继续显示 {{ Math.min(20,selectedSources.length-visibleSourceCount) }} 篇文献</button></div></section>
          </div>
        </div>
        <section v-else-if="tab === 'reviews'" class="surface review-workspace"><div class="surface-header"><div><h2>已有综述 × 细分方向</h2><p>逐项核对覆盖范围，判断可以增加哪些内容。</p></div><span class="pill">{{ report.reviews.length }} 篇综述</span></div><div v-if="!reviews.length" class="empty-state"><div class="empty-icon"><Icon name="book" :size="25" /></div><h3>当前资料中尚未识别到综述</h3><p>这不能说明该领域没有综述。建议检查文章类型限制，并扩大日期范围补充检索。</p><el-button @click="$router.push(`/scan/new?run=${id}`)">调整检索范围</el-button></div><template v-else><div class="coverage-legend"><span v-for="(label,key) in coverageLabels" :key="key"><i :class="`coverage-dot ${key.toLowerCase()}`"></i>{{ label }}</span></div><p class="review-disclosure">摘要涉及与全文覆盖分别标记。深入 / 部分 / 未覆盖为编辑全文核对结果；未核实的单元格不会被当作研究空白。</p><div class="coverage-scroll" tabindex="0" aria-label="可横向滚动的综述覆盖矩阵"><table class="coverage-table"><thead><tr><th scope="col">已发表综述</th><th v-for="t in report.topics" :key="t.id" scope="col">{{ t.name }}</th></tr></thead><tbody><tr v-for="review in reviews.slice(0,reviewLimit)" :key="review.pmid"><th scope="row"><button class="paper-title" @click="inspect(review.pmid)">{{ review.title }}</button><small>{{ review.pubdate || '日期未提供' }} · PMID {{ review.pmid }}</small><small>检索截止日期：{{ reviewEntry(review.pmid).searchCutoff || '尚未核实' }}</small><details v-if="reviewEntry(review.pmid).scopeNote || reviewEntry(review.pmid).limitations" class="review-inventory-note"><summary>查看盘点记录</summary><p>{{ reviewEntry(review.pmid).scopeNote || '覆盖内容尚未核实' }}</p><p>{{ reviewEntry(review.pmid).limitations }}</p><small>{{ reviewEntry(review.pmid).editorStatus === 'CONFIRMED' ? '编辑已确认' : '待核实草稿' }}</small></details><button class="text-button" :disabled="running" @click="editReview(review.pmid)">盘点综述信息</button></th><td v-for="t in report.topics" :key="t.id"><button :class="['coverage-cell',coverage(t,review.pmid).status.toLowerCase()]" :disabled="running" :aria-label="`${t.name} · PMID ${review.pmid}：${coverageLabels[coverage(t,review.pmid).status]}，点击核对`" @click="editCoverage(t,review.pmid)"><i :class="`coverage-dot ${coverage(t,review.pmid).status.toLowerCase()}`"></i>{{ coverageLabels[coverage(t,review.pmid).status] }}<small v-if="coverage(t,review.pmid).verifiedFullText">人工核对全文</small></button></td></tr></tbody></table></div><div class="review-bottom"><span>覆盖状态是针对具体方向的判断。</span><el-button v-if="reviews.length > reviewLimit" @click="reviewLimit += 30">继续显示综述</el-button></div></template></section>
        <div v-else-if="tab === 'topics'" class="candidate-workspace"><div class="candidate-intro"><div><h2>从证据线索到可讨论的邀稿方案</h2><p>检查问题边界、既有综述差异和证据充分性，再决定保留、合并或暂缓。</p></div><el-button :disabled="running" @click="editCandidate()"><Icon name="plus" :size="15" />新建子议题</el-button></div><div v-if="!report.candidates.length" class="surface empty-state"><div class="empty-icon"><Icon name="spark" :size="26" /></div><h3>开始整理第一张子议题卡</h3><p>可以手动建立选题，或由 AI 根据本次文献生成有引文的候选草稿。<br />候选内容不会自动视为通过查新。</p><el-button type="primary" :disabled="running" @click="editCandidate()">新建子议题</el-button></div><article v-for="(card,i) in report.candidates" :key="card.id" class="surface candidate-card"><div class="candidate-card-heading"><div><div class="eyebrow">TOPIC PROPOSAL {{ String(i+1).padStart(2,'0') }}</div><h2>{{ card.title }}</h2></div><span :class="['decision-pill',card.status.toLowerCase()]">{{ decisionLabels[card.status] }}</span></div><div class="candidate-question">{{ card.question }}</div><dl><div><dt>为什么现在值得写</dt><dd>{{ card.whyNow }}</dd></div><div><dt>与既有综述的差异化假设 <span>待核实</span></dt><dd>{{ card.difference }}</dd></div><div><dt>文章边界与分工</dt><dd>{{ card.boundary }}</dd></div></dl><details class="candidate-outline"><summary>查看建议提纲</summary><ol><li v-for="(item,n) in card.outline" :key="n">{{ item }}</li></ol></details><p v-if="card.editorNote" class="candidate-editor-note">编辑备注：{{ card.editorNote }}</p><div class="candidate-footer"><div class="citation-links"><button v-for="(c,n) in card.citations" :key="n" class="citation-chip" @click="inspect(c.pmid,c)">PMID {{ c.pmid }}<span>查看引文</span></button></div><el-button :disabled="running" @click="editCandidate(card)"><Icon name="edit" :size="14" />编辑与决策</el-button></div></article></div>
      </template>
    </template>
    <el-dialog v-model="analysisDialog" title="AI 梳理与子议题提炼" width="540px" :close-on-click-modal="false"><div class="analysis-description"><p>使用 <strong>{{ activeModel()?.name }}</strong>，基于本次文献的标题和摘要生成主题、梳理笔记和候选子议题。</p><label class="field-label" for="analysis-limit">本轮分析范围</label><el-select id="analysis-limit" v-model="analysisLimit"><el-option v-for="n in [20,40,80]" :key="n" :value="n" :label="`最多 ${n} 篇`" /></el-select><p class="field-help">优先纳入综述，其余按检索排序等距取样；摘要可能截断，实际范围会随结果一同保存。模型调用可能产生费用。</p><div v-if="state?.persisted || report?.mode === 'AI'" class="evidence-notice amber">新结果会替换当前主题、笔记和选题卡。需要保留编辑内容时，请先导出。分析失败时保留当前版本。</div><p class="analysis-limit-note">所有输出均为待核实草稿。当前版本不自动检索综述全文、注册平台或期刊专题合集。</p><div v-if="analysisError" class="inline-error" role="alert">{{ analysisError }}</div></div><template #footer><el-button @click="analysisDialog = false">取消</el-button><el-button type="primary" :loading="starting" @click="startAnalysis">开始生成草稿</el-button></template></el-dialog>
    <EvidenceEditor :open="editorOpen" :type="editorType" :value="editorValue" :sources="report?.sources || []" :saving="saving" :error="saveError" @close="editorOpen = false" @save="saveEdit" @inspect="inspect" />
    <el-drawer v-model="drawer" title="来源文献与引文核对" :size="drawerSize" class="evidence-source-drawer"><div v-if="sourceLoading"><el-skeleton :rows="8" animated /></div><div v-else-if="sourceError" class="inline-error" role="alert">{{ sourceError }}</div><template v-else-if="sourceArticle"><div class="source-meta"><span class="pill">PMID {{ sourceArticle.pmid }}</span><span>{{ sourceArticle.pubdate }}</span><span>{{ sourceArticle.pubtypes }}</span></div><h2 class="source-title">{{ sourceArticle.title }}</h2><p class="source-authors">{{ sourceArticle.authors }}</p><a :href="`https://pubmed.ncbi.nlm.nih.gov/${sourceArticle.pmid}/`" target="_blank" rel="noopener noreferrer" class="source-link">在 PubMed 查看原始记录 <Icon name="external" :size="13" /></a><section v-if="selectedCitation" class="source-quote"><strong>用于本条判断的原文片段</strong><span class="pill">{{ selectedCitation.field === 'title' ? '标题' : '摘要' }}</span><blockquote>{{ selectedCitation.quote }}</blockquote><small>生成时已校验该片段存在于提供的文本中；请结合当前来源上下文核对判断。</small></section><section class="source-abstract"><h3>原文摘要</h3><p>{{ sourceArticle.abstractText || 'PubMed 未提供摘要，请通过原始链接查看可获取的全文。' }}</p></section><details class="source-translation"><summary>查看标题与摘要的中文翻译</summary><TranslatedText :article-id="sourceArticle.id" field="title" :text="sourceArticle.title" block /><TranslatedText :article-id="sourceArticle.id" field="abstract" :text="sourceArticle.abstractText" block /></details><section class="source-contacts"><h3>作者 / 专家邮箱</h3><ArticleEmails :contacts="sourceArticle.emailContacts" expanded /></section></template></el-drawer>
  </div>
</template>
<script setup>
import { ref, computed, watch, onBeforeUnmount } from 'vue'
import { ElMessage } from 'element-plus'
import api from '../api'
import Icon from '../components/WorkbenchIcon.vue'
import EvidenceGraph from '../components/EvidenceGraph.vue'
import EvidenceEditor from '../components/EvidenceEditor.vue'
import TranslatedText from '../components/TranslatedText.vue'
import ArticleEmails from '../components/ArticleEmails.vue'
import { activeModel } from '../lib/models'
import { errorMessage } from '../lib/search'
import { authorEvidence, exportNotes, noteLabels, coverageLabels, maturityLabels, decisionLabels, elapsedTime } from '../lib/evidence'
import '../styles/evidence.css'
const props = defineProps({ id: String })
const state = ref(null), loading = ref(false), error = ref(''), tab = ref('map'), selectedId = ref(''), visibleSourceCount = ref(8), reviewLimit = ref(30)
const job = ref({ status: 'IDLE' }), analysisDialog = ref(false), analysisLimit = ref(40), analysisError = ref(''), starting = ref(false)
const editorOpen = ref(false), editorType = ref(''), editorValue = ref({}), editRevision = ref(0), saving = ref(false), saveError = ref('')
const drawer = ref(false), sourceArticle = ref(null), sourceLoading = ref(false), sourceError = ref(''), selectedCitation = ref(null)
let sequence = 0, sourceSequence = 0, viewEpoch = 0, pollTimer, elapsedTimer, disposed = false
const clock = ref(Date.now())
const elapsedLabel = computed(() => elapsedTime(job.value.startedAt, clock.value))
watch(() => job.value.status, status => { clearInterval(elapsedTimer); clock.value = Date.now(); if (status === 'RUNNING') elapsedTimer = setInterval(() => { clock.value = Date.now() }, 1000) })
const report = computed(() => state.value?.report), selected = computed(() => report.value?.topics.find(t => t.id === selectedId.value))
const selectedSources = computed(() => { const pmids = new Set(selected.value?.pmids || []); return (report.value?.sources || []).filter(s => pmids.has(s.pmid)) })
const authors = computed(() => authorEvidence(selected.value, report.value?.sources))
const reviews = computed(() => (report.value?.sources || []).filter(s => s.isReview))
const running = computed(() => job.value.status === 'RUNNING' || starting.value)
const canAnalyze = computed(() => Boolean(activeModel() && report.value?.analyzedCount && !running.value && !loading.value && !editorOpen.value))
const drawerSize = computed(() => typeof window !== 'undefined' && window.innerWidth < 760 ? '95%' : 'min(780px, 82vw)')
const emptyNotes = { CONSENSUS: '尚未形成有依据的共识判断。可以添加笔记，或使用 AI 提取待核实线索。', CONTROVERSY: '尚未整理出可比较的分歧。研究对象和终点不同，不能直接判断为结论冲突。', GAP: '尚未确认研究或综述缺口。文献少、未检出或未分类，均不能单独作为空白依据。', CONTEXT: '记录这个方向的关键问题、术语、适用条件和研究背景。' }
function apply(data) { state.value = data; job.value = data.job || { status: 'IDLE' }; if (!data.report.topics.some(t => t.id === selectedId.value)) selectedId.value = data.report.topics[0]?.id || '' }
async function load() {
  const current = ++sequence, id = props.id; loading.value = true; error.value = ''
  try { const { data } = await api.get(`/scans/${id}/evidence`); if (current !== sequence || id !== props.id || disposed) return; apply(data); if (data.job?.status === 'RUNNING') schedulePoll(id) }
  catch (e) { if (current === sequence && !disposed) error.value = errorMessage(e, '领域梳理暂时无法加载，请重试') }
  finally { if (current === sequence) loading.value = false }
}
function schedulePoll(id) { const epoch = viewEpoch; clearTimeout(pollTimer); pollTimer = setTimeout(() => poll(id, epoch), 1800) }
async function poll(id, epoch) {
  if (id !== props.id || epoch !== viewEpoch || disposed) return
  try { const { data } = await api.get(`/scans/${id}/evidence/job`); if (id !== props.id || epoch !== viewEpoch || disposed) return; job.value = data; if (data.status === 'RUNNING') schedulePoll(id); else if (data.status === 'COMPLETE') { await load(); if (epoch === viewEpoch && !disposed) ElMessage.success('梳理草稿已生成，请核对来源与主题边界') } }
  catch { if (id === props.id && epoch === viewEpoch && !disposed) schedulePoll(id) }
}
async function startAnalysis() {
  const id = props.id, epoch = viewEpoch; starting.value = true; analysisError.value = ''
  try { const { data } = await api.post(`/scans/${id}/evidence/analyze`, { revision: state.value.revision, limit: analysisLimit.value }); if (id !== props.id || epoch !== viewEpoch || disposed) return; job.value = data; analysisDialog.value = false; schedulePoll(id) }
  catch (e) { if (id === props.id && epoch === viewEpoch && !disposed) analysisError.value = errorMessage(e, '分析未启动，请检查模型设置后重试') }
  finally { if (id === props.id && epoch === viewEpoch) starting.value = false }
}
function selectTopic(id) { selectedId.value = id; visibleSourceCount.value = 8 }
function assignment(pmid) { return selected.value?.assignments?.find(a => a.pmid === pmid)?.basis || '' }
function coverage(topic, pmid) { return topic.coverage.find(c => c.reviewPmid === pmid) || { reviewPmid: pmid, status: 'UNVERIFIED', rationale: '', citations: [] } }
function openEditor(type, value) { editorType.value = type; editorValue.value = value; editRevision.value = state.value.revision; saveError.value = ''; editorOpen.value = true }
function editTopic() { openEditor('topic', { ...selected.value, topicId: selectedId.value }) }
function editNote(note, kind = 'CONTEXT') { openEditor('note', { topicId: selectedId.value, ...(note || { kind, text: '', editorStatus: 'DRAFT', citations: [] }) }) }
function reviewEntry(pmid) { return report.value?.reviewInventory?.find(r => r.pmid === pmid) || { pmid, searchCutoff: '', scopeNote: '', limitations: '', editorStatus: 'DRAFT' } }
function editReview(pmid) { openEditor('review', reviewEntry(pmid)) }
function editCoverage(topic, pmid) { openEditor('coverage', { topicId: topic.id, ...coverage(topic, pmid) }) }
function editCandidate(card) { openEditor('candidate', card || { title: '', question: '', whyNow: '', difference: '', boundary: '', outline: [], status: 'PENDING', editorNote: '', citations: [] }) }
async function saveEdit(value) {
  const id = props.id, epoch = viewEpoch; saving.value = true; saveError.value = ''
  try { const { data } = await api.patch(`/scans/${id}/evidence`, { ...value, operation: editorType.value, revision: editRevision.value }); if (id !== props.id || epoch !== viewEpoch || disposed) return; apply(data); editorOpen.value = false; ElMessage.success('修改已保存') }
  catch (e) { if (id === props.id && epoch === viewEpoch && !disposed) saveError.value = errorMessage(e, '保存失败，请重试') }
  finally { if (id === props.id && epoch === viewEpoch) saving.value = false }
}
async function inspect(pmid, citation = null) {
  if (!pmid) return; const current = ++sourceSequence, id = props.id
  selectedCitation.value = citation; sourceArticle.value = null; sourceError.value = ''; drawer.value = true; sourceLoading.value = true
  try { const { data } = await api.get(`/scans/${id}/evidence/articles/${pmid}`); if (current === sourceSequence && id === props.id && !disposed) sourceArticle.value = data }
  catch (e) { if (current === sourceSequence && !disposed) sourceError.value = errorMessage(e, '来源文献加载失败') }
  finally { if (current === sourceSequence) sourceLoading.value = false }
}
function download() { const blob = new Blob([exportNotes(state.value)], { type: 'text/markdown;charset=utf-8' }), url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = `领域梳理-${props.id}-v${state.value.revision}.md`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
function formatDate(value) { return value ? value.replace('T', ' ').slice(0, 16) : '—' }
watch(() => props.id, () => { ++viewEpoch; ++sequence; ++sourceSequence; clearTimeout(pollTimer); state.value = null; selectedId.value = ''; error.value = ''; job.value = { status: 'IDLE' }; tab.value = 'map'; drawer.value = false; editorOpen.value = false; analysisDialog.value = false; starting.value = false; saving.value = false; reviewLimit.value = 30; load() }, { immediate: true })
onBeforeUnmount(() => { disposed = true; ++sequence; ++sourceSequence; clearTimeout(pollTimer); clearInterval(elapsedTimer) })
</script>
